/* O·X가 반반 나오게: 맞는 말이 더 많은 목록에서도 O만 고르면 맞히지 못하게 (11/3 점검) */
const pickOX = list => { const want = Math.random() < .5 ? 'O' : 'X', sub = list.filter(x => x[1] === want); return pick(sub.length ? sub : list); };
const oxOf = (key, list, hint) => { const [st, a] = pickOX(list); return kox(key + st, st, a, hint); };
/* 상황 문장을 보여 주고 고르기: [상황, 정답, 오답, 오답] (11/4) */
const kSit = (key, type, prompt, list, hint, extra = {}) => { const [s, a, w1, w2] = pick(list); return kc(key + s, type, prompt, Object.assign({ say:`${s} ${prompt}`, read:s, vis:{ k:'html', html:`<div class="sent text-q">${esc(s)}</div>` }, opts:[a, w1, w2], ans:a, hint, explain:`${s} → ${a}` }, extra)); };
/* 글 + 물음 하나: p = { t, name? }, q = [물음, 정답, 오답, 오답] */
const kPassQ = (key, type, p, q, hint, extra = {}) => { const [qq, a, ...w] = q; return kc(key + qq, type, qq, Object.assign({ read:p.t.replace(/\n/g, ' '), vis:{ k:'html', html:(p.name ? `<span class="eyebrow">${esc(p.name)}</span>` : '') + passHTML(p.t) }, opts:[a, ...w], ans:a, hint, explain:a }, extra)); };
const nmOf = n => n + (hasBatchim(n) ? '이' : '');
