    const kid = pick(K1_KIDS), nm = kid.n + (hasBatchim(kid.n) ? '이' : ''), f = pick([['like',`${nm}가 좋아하는 것은?`],['good',`${nm}가 잘하는 것은?`],['dream',`${nm}의 꿈은?`],['food',`${nm}가 가장 좋아하는 음식은?`]]);
